<script setup lang="ts">
useSeoMeta({title:'Seoul',description:'Explore Seoul by neighborhood with practical local routes.'})
const {$supabase}=useNuxtApp(); const {data:neighborhoods}=await useAsyncData('seoul-neighborhoods',async()=>{const {data,error}=await $supabase.from('neighborhoods').select('id,name,slug,summary').order('name'); if(error) throw error; return data})
</script>
<template><main><section class="border-b border-[var(--brand-border)] bg-white"><div class="mx-auto max-w-7xl px-5 py-16"><p class="text-sm text-[var(--brand-muted)]">Home / Destinations</p><h1 class="mt-4 text-5xl font-semibold">Seoul</h1><p class="mt-3 max-w-xl text-[var(--brand-muted)]">A city of tradition, culture and endless new stories.</p></div></section><section class="mx-auto max-w-7xl px-5 py-10"><h2 class="mb-5 text-2xl font-semibold">Explore by area</h2><div class="grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><NuxtLink v-for="n in neighborhoods || []" :key="n.id" :to="n.slug==='seongsu'?'/seongsu':'#'" class="rounded-2xl border border-[var(--brand-border)] bg-white p-5"><div class="mb-4 aspect-[16/10] rounded-xl bg-neutral-200"/><h3 class="font-semibold">{{n.name}}</h3><p class="mt-1 text-sm text-[var(--brand-muted)]">{{n.summary}}</p></NuxtLink></div></section></main></template>
